// Pseudo: obtain per-tenant DEK, encrypt, store ciphertext with key reference
async function ingestEvent(tenantId, plaintext) {
  const dek = await kms.getTenantDEK(tenantId);
  const iv = crypto.randomBytes(12);
  const ciphertext = crypto.aesGCM(plaintext, dek.key, iv);
  await storeCiphertext(tenantId, ciphertext, iv, dek.id);
}
```

