// Pseudo KCNA sink skeleton
class EnrichmentSink {
  constructor() { this.profileStore = new Map(); }
  onMessage(clickEvent) {
    const p = this.profileStore.get(clickEvent.userId);
    if (p) {
      this.emit({ ...clickEvent, profile: p });
    } else {
      // could hold or emit with null profile depending on policy
    }
  }
  onProfileUpdate(userId, profile) {
    this.profileStore.set(userId, profile);
  }
}
```

